import os, hashlib, sqlite3

def get_hashes(dirpath):
    hashes = {}
    for root, dirs, files in os.walk(dirpath):
        for f in files:
            if f.endswith(".mp4"):
                p = os.path.join(root, f)
                try:
                    with open(p, "rb") as fp:
